function journeyRaceMarkup(r,division){
 const target=division>1?'승격권':'TOP 6',status={achieved:target+' 목표 달성',missed:target+' 목표 미달',secured:target+' 승점 확보',out:target+' 추격 종료',open:target+' 경쟁 진행 중'}[r.status],esc=escapeText;
 return '<section class="journey-race" aria-label="승점으로 보는 시즌 경쟁"><div class="journey-race-heading"><strong>'+status+'</strong><span>남은 리그 '+r.remaining+'경기</span></div><p>'+(r.status==='secured'?'다른 팀이 남은 경기를 모두 이겨도 목표 순위 밖으로 밀려나지 않습니다.':r.status==='out'?'남은 경기를 모두 이겨도 목표 순위에 도달할 수 없습니다.':r.remaining?'우리 팀이 얻을 수 있는 최대 승점은 '+r.maximum+'점입니다.':'최종 순위는 '+r.rank+'위입니다.')+'</p>'+(r.nextRival?'<p class="journey-race-opponent">다음 리그 상대 · '+esc(r.nextRival.name)+' · '+r.nextRival.rank+'위 / '+r.nextRival.points+'점</p>':'')+'<ol>'+r.contenders.map(c=>'<li><span>'+c.rank+'위 · '+esc(c.name)+'</span><strong>'+c.points+'점 <small>('+(c.gap>0?'우리보다 +'+c.gap:c.gap<0?'우리보다 '+c.gap:'승점 동률')+')</small></strong></li>').join('')+'</ol><small>확정 리그 기록 기준 · 승점 동률은 골득실로 순위가 바뀔 수 있습니다. 컵 결과는 제외합니다.</small></section>';
}
function renderManagerJourney(){
 if(view!=='club')return;
 const host=$('manager-journey');if(!host)return;
 const model=ManagerJourney.read(season),s=model.season,esc=escapeText;
 const challenge=model.challenge,challengeMarkup=challenge?'<section class="journey-campaign" aria-label="현재 시즌 목표"><div><span class="eyebrow">SEASON TARGET</span><strong>'+esc(challenge.title)+'</strong></div><p>'+esc(challenge.detail)+'</p><small>'+challenge.played+' / '+challenge.total+'경기 확정 · 현재 '+challenge.points+'점</small></section>':'';
 const chapter=typeof managerStoryChapter==='function'?managerStoryChapter(s):null,chapterMarkup=chapter?'<div class="manager-chapter"><small>가상 스토리 · 현재 시즌</small><h3>'+esc(chapter[0])+'</h3><p>'+esc(chapter[1])+'</p></div>':'';
 const ladder=model.ladder,tierNames=['Premier League','Championship','League One','League Two','National League'],ladderMarkup=ladder?'<section class="journey-ladder" aria-label="5부에서 1부까지 승격 경로"><div class="journey-ladder-heading"><strong>5부에서 1부까지</strong><span>1부까지 '+ladder.stepsRemaining+'계단</span></div><ol>'+ladder.tiers.map(t=>'<li class="'+(t.current?'current':t.visited?'passed':'ahead')+'"><span class="journey-tier-marker">'+(t.current?'●':t.visited?'✓':'○')+'</span><span><b>'+t.tier+'부</b><small>'+tierNames[t.tier-1]+'</small></span>'+(t.current?'<em>현재</em>':t.visited?'<em>경험</em>':'')+'</li>').join('')+'</ol><p>'+(ladder.nextTier?'이번 시즌 목표: '+esc(ladder.nextTier)+' 승격권 진입.':'최종 목표: 1부 잔류와 유럽 무대.')+'</p></section>':'';
 const arc=model.arc,arcMarkup=arc?'<section class="journey-arc" aria-live="polite"><div><span class="eyebrow">'+(arc.round===arc.total?'SEASON FINALE':'THE SEASON SO FAR')+'</span><strong>'+esc(arc.headline)+'</strong></div><p>'+esc(arc.copy)+'</p><div class="journey-form" aria-label="최근 확정 경기 흐름">'+(arc.form.length?arc.form.map((result,i)=>'<span class="form-'+result.toLowerCase()+'" aria-label="최근 '+(arc.form.length-i)+'번째 경기 '+({W:'승리',D:'무승부',L:'패배'}[result])+'">'+result+'</span>').join(''):'<span class="form-empty">첫 경기 전</span>')+'</div></section>':'';
 const expanded=host.querySelector('details')?.open||false;
 host.innerHTML=`<section class="manager-journey-card" aria-labelledby="manager-journey-title"><div class="journey-heading"><div><span class="eyebrow">THE ROAD BACK · MANAGER STORY</span><h2 id="manager-journey-title">${ladder?'5부에서 시작하는 1부 귀환':'우승까지의 여정'}</h2></div><span class="journey-count">${model.completed} / ${model.total} 달성</span></div>${ladderMarkup}${challengeMarkup}<div class="journey-season"><span>${s.year}시즌 · ${s.division}부 · ${s.rank?s.rank+"위 · "+s.points+"점":"첫 경기 준비"}</span><span>${s.final?"리그 종료":"리그 "+s.remaining+"경기 남음"}</span></div><progress max="${s.total}" value="${s.played}" aria-label="확정된 리그 경기 ${s.played} / ${s.total}"></progress><details${expanded?" open":""}><summary>승격 경쟁 · 시즌 이야기 · 이정표</summary>${journeyRaceMarkup(model.race,s.division)}${arcMarkup}${chapterMarkup}<p class="journey-next"><strong>${model.next?'다음 도전 · '+esc(model.next.title):'모든 이정표 달성 · 이제 왕조를 이어가세요'}</strong><span>${model.next?esc(model.next.hint):'다음 시즌에도 새로운 선수와 함께 우승에 도전할 수 있습니다.'}</span></p><ol class="journey-milestones">${model.milestones.map(m=>`<li class="${m.achieved?'achieved':''}"><span class="journey-marker" aria-hidden="true">${m.achieved?'✓':'○'}</span><div><strong>${esc(m.title)}</strong><small>${m.achieved?'달성 · '+esc(m.evidence):esc(m.hint)}</small></div></li>`).join('')}</ol><p class="journey-carry">${esc(model.carry)}</p>${model.partial?'<p class="journey-carry">이전 저장에 없는 승리 기록은 추정하지 않습니다. 남아 있는 확정 기록부터 표시합니다.</p>':''}<p class="journey-carry">목표는 각각 달성할 수 있으며, 이정표 자체로 추가 자금이나 능력치를 지급하지 않습니다.</p></details><div class="journey-actions"><button type="button" id="journey-continue" class="secondary">${{season:'다음 시즌 준비',result:'경기 결과 확정하러 가기',match:'다음 경기 준비'}[model.action]}</button><button type="button" id="journey-competitions" class="text-button">대회 기록 보기 →</button></div></section>`;
 $('journey-continue').onclick=()=>{if(model.action==='season'){setMobileDashboardExpanded(true);$('next-season')?.scrollIntoView({block:'center',behavior:'instant'});$('next-season')?.focus({preventScroll:true});}else setView('match');};
 $('journey-competitions').onclick=()=>setView('cup');
}
